import { readFileSync } from "node:fs";
import { assertProductionConfig } from "../src/lib/production-config.ts";

// The standalone server serializes next.config and bypasses its start phase.
// Apply the SAME production protection before starting the generated server.
const builtUrl = JSON.parse(
  readFileSync(new URL("../build-public-url.json", import.meta.url), "utf8"),
);
if (process.env.NEXT_PUBLIC_APP_URL !== builtUrl) {
  throw new Error(
    "NEXT_PUBLIC_APP_URL differs from the build; rebuild the image",
  );
}
assertProductionConfig(process.env);
// Generated by Next's standalone build, absent from the source checkout.
await import("../server.js");
